--
-- Table structure for table `npcregionspawns`
--
-- THE belt-spawn table, loot-table style: one row = one NPC type allowed in a
-- region's belts. maxSec = highest security the type appears in (spawns there
-- and below). factionID/corporationID own each spawned ball.
--

DROP TABLE IF EXISTS `npcregionspawns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `npcregionspawns` (
  `spawnID` int(11) NOT NULL AUTO_INCREMENT,
  `regionID` int(11) NOT NULL,
  `typeID` int(11) NOT NULL,
  `maxSec` double NOT NULL DEFAULT 1,
  `weight` int(11) NOT NULL DEFAULT 1,
  `shipClass` varchar(32) NOT NULL DEFAULT 'frigate',
  `role` varchar(32) NOT NULL DEFAULT 'normal',
  `brainProfile` varchar(64) NOT NULL DEFAULT 'aggressive',
  `factionID` int(11) NOT NULL DEFAULT 0,
  `corporationID` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`spawnID`),
  KEY `idx_region` (`regionID`)
) ENGINE=InnoDB AUTO_INCREMENT=9677 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

